  length (ws ++ rest) = 255%nat -> (TR + 2040 <= 2^63)%Z ->
  mem_inv asegs m ->
  evt asegs (depot_put_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc D BK DNB SSB TR ws rest lo m)
